//! The generated support matrix (`docs/support-matrix.md`).

use std::fmt::Write;

use vynamp_output_core::{Feature, HostId, support};

/// Renders the support matrix as markdown, with `\n` line endings.
///
/// `cargo run -p vynamp-output --example support_matrix` prints this text and
/// `docs/support-matrix.md` is its committed copy; a test keeps them equal.
pub fn support_matrix_markdown() -> String {
    let mut s = String::new();
    s.push_str("# Support matrix\n\n");
    s.push_str(
        "Generated by `cargo run -p vynamp-output --example support_matrix`; do not edit by hand.\n\
         A test fails if this file differs from the generator output.\n\n",
    );
    s.push_str("Each cell is the strongest verification level the host declares for the feature\n");
    s.push_str("(`-` means not implemented in this release).\n\n");
    s.push_str("| host |");
    for f in Feature::ALL {
        let _ = write!(s, " {} |", f.name());
    }
    s.push_str("\n|---|");
    for _ in Feature::ALL {
        s.push_str("---|");
    }
    s.push('\n');
    for host in HostId::ALL {
        let _ = write!(s, "| {} |", host.name());
        for f in Feature::ALL {
            let cell = support(host, f).map_or("-", |l| l.name());
            let _ = write!(s, " {cell} |");
        }
        s.push('\n');
    }
    s.push_str("\n## Levels\n\n");
    s.push_str(
        "- `capture-verified`: delivered bytes compared bit for bit at a point that includes the OS path.\n\
         - `hardware-verified`: a manual entry in [hardware-matrix.md](hardware-matrix.md).\n\
         - `integration`: opened, played, drained and lost on the real OS stack in CI.\n\
         - `library-verified`: proven by the Null and Capture hosts in every CI run.\n\
         - `compiled`: the target builds; nothing was run (macOS stays here until a Mac agent exists).\n",
    );
    s
}
